mapper.select:
select c.id, c.user_id, c.content, c.create_time, c.video_id, u.nickname, u.avatar as avatarKey from comment c left join user u on c.user_id = u.id where video_id = #{id}
and (c.create_time < #{cursorTime} or (c.create_time = #{cursorTime} and c.id < #{cursorId}) )
ORDER BY create_time DESC, id DESC LIMIT #{size}
